===ProductShowcase===
import Link from "next/link";
import { Reveal } from "./Reveal";
import { IconServer, IconGame, IconDisk, IconGlobe, IconMail, IconApps, IconArrow } from "./icons";
import { ClaudeMark } from "./ClaudeMark";

/**
 * The single grid that holds every Nxeon product. This is the core declutter
 * move for the homepage: instead of a full-width stacked section per product
 * (game servers, email, storage…), one tidy card grid surfaces them all with a
 * link out to each dedicated page — progressive disclosure done right.
 */

type Product = {
  label: string;
  href: string;
  blurb: string;
  icon: (p: { size?: number }) => React.ReactNode;
  accent: string; // tailwind gradient stops for the icon chip
  badge?: string;
};

const PRODUCTS: Product[] = [
  {
    label: "VPS Hosting",
    href: "/vps",
    blurb: "Full-root KVM servers on enterprise NVMe. Resize anytime, dedicated IP, DDoS protection.",
    icon: IconServer,
    accent: "from-accent-blue/30 to-brand-500/30",
  },
  {
    label: "Web Hosting",
    href: "/web-hosting",
    blurb: "One-click WordPress, free SSL and email on your domain — a friendly panel, no server to manage.",
    icon: IconApps,
    accent: "from-accent-cyan/30 to-brand-500/30",
    badge: "New",
  },
  {
    label: "Game Servers",
    href: "/game-servers",
    blurb: "Minecraft, Rust, Valheim, Palworld and more — low-latency, auto-updating, one-click deploy.",
    icon: IconGame,
    accent: "from-emerald-500/30 to-accent-cyan/30",
  },
  {
    label: "Claude AI Builder",
    href: "/features",
    blurb: "Describe what you want in plain English and Claude configures your server for you.",
    icon: ClaudeMark,
    accent: "from-[#D97757]/25 to-brand-500/25",
    badge: "New",
  },
  {
    label: "Block Storage",
    href: "/block-storage",
    blurb: "Attach expandable NVMe volumes to any server. Grow your storage without resizing the box.",
    icon: IconDisk,
    accent: "from-brand-500/30 to-brand-700/30",
  },
  {
    label: "Domains",
    href: "/domains",
    blurb: "Register and manage domains at cost-plus pricing, with one-click DNS to point at your VPS.",
    icon: IconGlobe,
    accent: "from-accent-cyan/30 to-accent-blue/30",
  },
  {
    label: "Business Email",
    href: "/business-email",
    blurb: "Professional mailboxes on your own domain — inbox, calendar, and contacts included.",
    icon: IconMail,
    accent: "from-brand-400/30 to-brand-600/30",
  },
];

export function ProductShowcase() {
  return (
    <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
      {PRODUCTS.map((p, i) => (
        <Reveal key={p.label} delay={i * 50} className="h-full">
          <Link href={p.href} className="card lift group flex h-full flex-col">
            <div className="flex items-center justify-between">
              <span className={`flex h-11 w-11 items-center justify-center rounded-xl bg-gradient-to-br ${p.accent} text-white ring-1 ring-white/10`}>
                {p.icon({ size: 20 })}
              </span>
              {p.badge && (
                <span className="rounded-full bg-brand-500/20 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-brand-200">
                  {p.badge}
                </span>
              )}
            </div>
            <h3 className="mt-4 text-lg font-semibold text-white">{p.label}</h3>
            <p className="mt-1.5 flex-1 text-sm leading-relaxed text-slate-400">{p.blurb}</p>
            <span className="mt-4 inline-flex items-center gap-1.5 text-sm font-medium text-brand-300 transition-transform group-hover:translate-x-0.5">
              Learn more <IconArrow size={15} />
            </span>
          </Link>
        </Reveal>
      ))}
    </div>
  );
}
